<script setup>
import {useUiText} from "../ui-text";
const ui=useUiText();

import {computed,ref,watch,onUnmounted} from 'vue';
import {searchPredicate} from '../../shared/search.mjs';
import {Languages,Search,Star,Shuffle,Plus,X,ChevronDown,Undo2,Redo2,History,ArrowLeft,ArrowRight,Eye,EyeOff,Trash2,CornerDownLeft,RefreshCw} from 'lucide-vue-next';
import {useStudio,api} from '../store';
import TagBrowser from './TagBrowser.vue';
import {splitTags,formatPrompt,appendPrompt,adjustWeight,uniquePrompt,updatePromptTag,breakAfterTag,movePromptTag} from '../editor/prompts';
const props=defineProps({modelValue:String,negative:Boolean,scope:String});const emit=defineEmits(['update:modelValue']);const s=useStudio();
const editing=ref(null),show=ref(false),translating=ref(false);
const dragIndex=ref(null),dragTarget=ref(null);let dragText='';
const undoStack=ref([]),redoStack=ref([]),historyOpen=ref(false),quickBusy=ref(false),quickError=ref(''),composing=ref(false),quickInput=ref();let formatTimer,quickTimer,quickRevision=0;
const value=computed({get:()=>props.modelValue||'',set:v=>{if(v!==value.value){undoStack.value.push(value.value);if(undoStack.value.length>60)undoStack.value.shift();redoStack.value=[];emit('update:modelValue',v);}}});
const fieldKey=computed(()=>s.config.activeProfile+':'+(props.scope||'generate')+':'+(props.negative?'negative':'positive'));
const quickDraft=computed({get:()=>s.config.quickPromptDrafts?.[fieldKey.value]?.text||'',set:text=>{const all=s.config.quickPromptDrafts||(s.config.quickPromptDrafts={});all[fieldKey.value]={...(all[fieldKey.value]||{}),text};}});
const savedHistory=computed(()=>s.config.promptHistory?.[fieldKey.value]||[]);
const disabledTags=computed(()=>s.config.disabledPromptTags?.[fieldKey.value]||[]);
const allTags=computed(()=>[...s.tags,...(s.config.customTags||[])]);
const favorites=computed(()=>s.config.favoriteTags||[]);
const tokens=computed(()=>splitTags(value.value));
const translated=ref({}),translationState=ref('idle');let translationTimer,translationRevision=0;
const baseTag=token=>token.replace(/^\(+|\)+$/g,'').replace(/:[\d.]+$/,'').replaceAll('_',' ').trim().toLowerCase();
const explanation=token=>allTags.value.find(tag=>tag.zh&&baseTag(tag.en)===baseTag(token))?.zh||translated.value[token]||(/[\u4e00-\u9fff]/.test(token)?token:translationState.value==='error'?s.t('翻译未完成，可重新开启重试','Toggle translation to retry'):s.t('翻译中…','Translating…'));
watch([tokens,()=>s.config.liveTagTranslation],()=>{clearTimeout(translationTimer);const revision=++translationRevision;if(!s.config.liveTagTranslation||!tokens.value.length)return;const missing=tokens.value.filter(token=>!allTags.value.some(tag=>tag.zh&&baseTag(tag.en)===baseTag(token))&&!translated.value[token]&&!/[\u4e00-\u9fff]/.test(token));if(!missing.length)return;translationState.value='loading';translationTimer=setTimeout(async()=>{try{const result=await api('translate/tags',{tags:[...new Set(missing)].slice(0,120)});const valid={...result.translations};for(const tag of result.unresolved||[])delete valid[tag];Object.assign(translated.value,valid);if(revision===translationRevision)translationState.value=result.partial?'error':'idle';}catch{if(revision===translationRevision)translationState.value='error';}},450);},{immediate:true});
onUnmounted(()=>{clearTimeout(translationTimer);clearTimeout(formatTimer);clearTimeout(quickTimer);});
const suggestions=computed(()=>{const q=value.value.split(/[,，\n]/).at(-1)?.trim(),match=searchPredicate(q);if(!q||q.length<2||q.length>48)return [];return allTags.value.filter(t=>match(t.en,t.zh)).sort((a,b)=>{const exact=t=>[t.en,t.zh].some(v=>v?.toLowerCase().replaceAll('_',' ')===q.toLowerCase().replaceAll('_',' '));return Number(exact(b))-Number(exact(a))||a.en.length-b.en.length;}).slice(0,5);});
async function refreshTagTranslations(){translationState.value='loading';try{const result=await api('translate/tags',{tags:[...new Set(tokens.value)].slice(0,120)});const valid={...result.translations};for(const tag of result.unresolved||[])delete valid[tag];Object.assign(translated.value,valid);translationState.value=result.partial?'error':'idle';s.notify(result.partial?result.message:'标签翻译已刷新 · '+(result.sources||[]).join('、'));}catch(e){translationState.value='error';s.notify(e.message,'error');}}
function saveEdit(){if(!editing.value)return;value.value=updatePromptTag(value.value,editing.value.index,()=>[editing.value.text]);editing.value=null;}
function remember(){const text=formatPrompt(value.value);if(!text.trim())return;const all=s.config.promptHistory||(s.config.promptHistory={}),list=all[fieldKey.value]||[];all[fieldKey.value]=[{text,date:new Date().toISOString()},...list.filter(item=>item.text!==text)].slice(0,40);}
function normalize(){clearTimeout(formatTimer);if(composing.value)return;value.value=formatPrompt(value.value);remember();}
function tidy(){clearTimeout(formatTimer);if(composing.value)return;formatTimer=setTimeout(()=>{const text=value.value;value.value=formatPrompt(text,{trailing:/[,，]\s*$/.test(text)});},400);}
function add(tag,replace=false){if(replace){const parts=splitTags(value.value);parts.pop();value.value=formatPrompt([...parts,tag.en].join(', '));}else value.value=appendPrompt(value.value,tag.en);remember();}
function remove(index){value.value=updatePromptTag(value.value,index,()=>[]);}
function weight(index,delta){value.value=updatePromptTag(value.value,index,t=>[adjustWeight(t,delta)]);}
function moveTag(index,offset){value.value=movePromptTag(value.value,index,index+offset);remember();}
function startDrag(event,index){if(event.target.closest('button')){event.preventDefault();return;}dragIndex.value=index;dragText=value.value;event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',tokens.value[index]);}
function endDrag(){dragIndex.value=null;dragTarget.value=null;dragText='';}
function dragOver(index){if(dragIndex.value!==null)dragTarget.value=index;}
function dropTag(event,index){event.preventDefault();if(dragIndex.value!==null&&dragText===value.value){value.value=movePromptTag(value.value,dragIndex.value,index);remember();}endDrag();}
function hideTag(index){const all=s.config.disabledPromptTags||(s.config.disabledPromptTags={});(all[fieldKey.value]||(all[fieldKey.value]=[])).push(tokens.value[index]);remove(index);}
function restoreTag(index){const list=s.config.disabledPromptTags[fieldKey.value];add({en:list[index]});list.splice(index,1);}
function undoPrompt(){if(!undoStack.value.length)return;redoStack.value.push(value.value);emit('update:modelValue',undoStack.value.pop());}
function redoPrompt(){if(!redoStack.value.length)return;undoStack.value.push(value.value);emit('update:modelValue',redoStack.value.pop());}
async function applyQuick(finish=false){clearTimeout(quickTimer);if(composing.value)return;const text=quickDraft.value.trim(),key=fieldKey.value,revision=++quickRevision;if(!text)return;quickBusy.value=true;quickError.value='';try{let english=text;if(/[\u4e00-\u9fff]/.test(text)){const translated=await api('translate',{text});if(translated.partial)throw Error(s.t('中文翻译未完成，请检查离线翻译模型','Offline translation is not ready'));english=translated.text;}if(revision!==quickRevision||key!==fieldKey.value)return;const draft=s.config.quickPromptDrafts[key],previous=draft.applied||'',current=formatPrompt(value.value);const base=previous&&current.endsWith(previous)?current.slice(0,-previous.length):current;const applied=formatPrompt(english);value.value=appendPrompt(base,applied);draft.applied=applied;remember();if(finish){draft.text='';draft.applied='';quickInput.value?.focus();}}catch(e){quickError.value=e.message;}finally{if(revision===quickRevision)quickBusy.value=false;}}
watch(quickDraft,text=>{clearTimeout(quickTimer);++quickRevision;if(!text.trim()){const draft=s.config.quickPromptDrafts?.[fieldKey.value];if(draft)draft.applied='';return;}if(!composing.value)quickTimer=setTimeout(()=>void applyQuick(),900);});
function finishComposition(){composing.value=false;tidy();if(quickDraft.value.trim()){clearTimeout(quickTimer);quickTimer=setTimeout(()=>void applyQuick(),900);}}
function favorite(tag){const list=s.config.favoriteTags||(s.config.favoriteTags=[]);const i=list.indexOf(tag.en);i>=0?list.splice(i,1):list.push(tag.en);}
async function translate(){translating.value=true;try{const data=await api('translate',{text:value.value});value.value=formatPrompt(data.text);remember();s.notify(data.partial?data.message:'翻译完成 · '+data.source+(data.fallback?'（已切换备用）':''));}catch(e){s.notify(e.message,'error');}finally{translating.value=false;}}
function random(){const list=allTags.value.filter(t=>['场景','环境','画面','镜头'].includes(t.category));const item=list[Math.floor(Math.random()*list.length)];if(item)add(item);}
</script>
<template><div :class="['prompt-field',{negative}]"><div class="field-title"><label>{{ui(negative?s.t('负面提示词','Negative prompt'):s.t('正面提示词','Positive prompt'))}}</label><span>{{ui(s.t('支持英文标签与自然语言','Tags and natural language'))}}</span><button class="text-button" @click="translate" :disabled="translating"><Languages :size="14"/>{{ui(translating?s.t('翻译中…','Translating…'):s.t('翻译成英文','Translate'))}}</button></div><div class="prompt-input-layout" v-resize-panels="{key:'prompt-input',config:s.config,min:[240,200],labels:['调整提示词与快捷输入宽度']}"><textarea v-model="value" @input="tidy" @blur="normalize" @compositionstart="composing=true" @compositionend="finishComposition" :aria-label="ui(negative?s.t('负面提示词','Negative prompt'):s.t('正面提示词','Positive prompt'))" :rows="negative?3:4" :placeholder="ui(negative?s.t('例如：模糊、画面变形、多余的手指','blurry, bad anatomy, extra fingers'):s.t('描述人物、动作、场景和画风。例如：一位旅行者走过宁静的小镇。','Describe the character, action, scene and style.'))"/><aside class="quick-prompt"><label>{{ui(s.t('中英文快捷输入','Quick prompt input'))}}</label><textarea ref="quickInput" v-model="quickDraft" :aria-label="ui(negative?s.t('负面快捷输入','Quick negative input'):s.t('正面快捷输入','Quick positive input'))" rows="3" :placeholder="ui(s.t('输入中文自动译成英文；英文直接加入。停顿后自动填入左侧，Enter 确认并继续。','Chinese translates automatically; English is added directly. Press Enter to finish.'))" @compositionstart="composing=true" @compositionend="finishComposition" @keydown.enter="if(!$event.isComposing){$event.preventDefault();applyQuick(true)}"/><button class="secondary" @click="applyQuick(true)" :disabled="quickBusy||!quickDraft.trim()">{{ui(quickBusy?s.t('正在翻译…','Translating…'):s.t('确认并继续输入','Finish and add another'))}}</button><small>{{ui(quickError||s.t('修改此处会更新刚加入的内容，不会反复堆叠。','Editing updates the last addition.'))}}</small></aside></div>
 <div v-if="suggestions.length" class="suggestions"><span>{{ui(s.t('标签联想','Suggestions'))}}</span><button v-for="tag in suggestions" @click="add(tag,true)">{{tag.en}} <small>{{tag.zh}}</small></button></div>
 <div class="prompt-actions"><button class="quiet" @click="normalize">{{ui(s.t('整理格式','Format'))}}</button><button class="quiet" @click="value=uniquePrompt(value)">{{ui(s.t('去重','Deduplicate'))}}</button><button class="icon-button" @click="undoPrompt" :disabled="!undoStack.length" :title="ui(s.t('撤销提示词修改','Undo prompt edit'))"><Undo2 :size="16"/></button><button class="icon-button" @click="redoPrompt" :disabled="!redoStack.length" :title="ui(s.t('重做提示词修改','Redo prompt edit'))"><Redo2 :size="16"/></button><button class="quiet" @click="historyOpen=!historyOpen"><History :size="15"/>{{ui(s.t('历史','History'))}}</button><button class="quiet" @click="remember();value=''"><Trash2 :size="15"/>{{ui(s.t('清空','Clear'))}}</button><button class="quiet" @click="show=!show"><Plus :size="14"/>{{ui(s.t('挑选标签','Browse tags'))}}<ChevronDown :size="13"/></button><button class="quiet" @click="random"><Shuffle :size="14"/>{{ui(s.t('随机灵感','Inspire me'))}}</button><label v-if="!negative" class="inline-check"><input type="checkbox" v-model="s.config.autoTranslate"/>{{ui(s.t('中文描述自动转英文','Translate Chinese input'))}}</label><label class="inline-check"><input type="checkbox" v-model="s.config.liveTagTranslation"/>{{ui(s.t('实时中文翻译','Live Chinese translations'))}}</label><button v-if="s.config.liveTagTranslation" class="quiet" @click="refreshTagTranslations" :disabled="translationState==='loading'" :aria-busy="translationState==='loading'"><RefreshCw :size="14"/>{{ui(translationState==='loading'?'翻译中…':'刷新翻译')}}</button><span class="muted push">{{ui(tokens.length)}} {{ui(s.t('个标签','tags'))}}</span></div>
 <div v-if="tokens.length" class="token-list"><span v-for="(token,i) in tokens" :key="i" class="token" :class="{dragging:dragIndex===i,'drag-target':dragTarget===i}" tabindex="0" draggable="true" :aria-label="ui('提示词标签 '+token)" @dragstart="startDrag($event,i)" @dragover.prevent="dragOver(i)" @drop="dropTag($event,i)" @dragend="endDrag" @keydown.alt.left.prevent="moveTag(i,-1)" @keydown.alt.right.prevent="moveTag(i,1)" :title="ui(s.config.liveTagTranslation?explanation(token):token)"><span class="token-top"><span class="token-en" @dblclick="editing={index:i,text:token}">{{token}}</span><span class="token-controls"><button @click="favorite({en:token})" :title="ui(s.t('收藏标签','Favorite tag'))"><Star :size="13" :fill="favorites.includes(token)?'currentColor':'none'"/></button><button @click="moveTag(i,-1)" :title="ui(s.t('标签左移','Move tag left'))"><ArrowLeft :size="13"/></button><button @click="moveTag(i,1)" :title="ui(s.t('标签右移','Move tag right'))"><ArrowRight :size="13"/></button><button @click="value=breakAfterTag(value,i)" :title="ui(&quot;在此标签后换行&quot;)"><CornerDownLeft :size="13"/></button><button @click="hideTag(i)" :title="ui(s.t('临时禁用标签','Disable tag'))"><Eye :size="13"/></button><button @click="weight(i,-0.1)" :title="ui(&quot;减少权重&quot;)">−</button><button @click="weight(i,0.1)" :title="ui(&quot;增加权重&quot;)">＋</button><button @click="remove(i)" :title="ui(&quot;移除标签&quot;)"><X :size="13"/></button></span></span><small v-if="s.config.liveTagTranslation" class="token-zh">{{explanation(token)}}</small></span></div>
 <div v-if="disabledTags.length" class="disabled-tags"><span>{{ui(s.t('已禁用（不会参与生成）','Disabled tags (excluded from generation)'))}}</span><button v-for="(tag,index) in disabledTags" @click="restoreTag(index)"><EyeOff :size="13"/>{{tag}} · {{ui(s.t('恢复','Restore'))}}</button></div><div v-if="historyOpen" class="prompt-history"><button v-for="item in savedHistory" @click="value=item.text;historyOpen=false"><small>{{ui(new Date(item.date).toLocaleString())}}</small><span>{{item.text}}</span></button><p v-if="!savedHistory.length">{{ui(s.t('编辑并离开输入框后，会记录到这里。','History is saved after editing.'))}}</p></div>
 <TagBrowser v-if="show" @select="add"/>
 <div v-if="editing" class="modal-backdrop" @click.self="saveEdit"><section class="modal"><div class="modal-dismiss-row"><button class="icon-button" :aria-label="ui(&quot;关闭标签编辑&quot;)" @click="editing=null"><X :size="20"/></button></div><div class="modal-title"><h2>{{ui(s.t('编辑标签','Edit tag'))}}</h2></div><label>{{ui(s.t('英文标签或权重表达式','English tag or weighted expression'))}}<input v-model="editing.text" :aria-label="ui(s.t('编辑标签内容','Tag text'))" @keydown.enter="saveEdit"/></label><div class="button-row"><button class="secondary" @click="editing=null">{{ui(s.t('取消','Cancel'))}}</button><button class="primary" @click="saveEdit">{{ui(s.t('保存标签','Save tag'))}}</button></div></section></div>
</div></template>
